UPDATE dcr01_class_tree
   SET dcr01_note = #{note}
 WHERE dcr01_class_tree_cd = #{classTreeCode}
   AND dcr01_company_id = #{companyId}

mapper.select:
SELECT t.dcr01_class_tree_id AS class_tree_id, t.dcr01_class_tree_cd AS class_tree_code, t.dcr01_class_tree_f_nm AS class_tree_full_name FROM ( SELECT a.dcr01_class_tree_id , a.dcr01_class_tree_cd , f_class_tree_nm_allpath(a.dcr01_class_tree_id) AS dcr01_class_tree_f_nm FROM dcr01_class_tree a WHERE 1=1 AND dcr01_company_id = #{companyId} AND dcr01_type_cd = #{typeCode} AND COALESCE(dcr01_use_yn, 'false') = 'true'
AND NOT EXISTS ( SELECT 1 FROM tdm47_manl_relate_dcr WHERE tdm47_dcr_class_tree_id = dcr01_class_tree_id AND tdm47_manl_id = #{relateId} )
) t WHERE CONCAT(t.dcr01_class_tree_cd, t.dcr01_class_tree_f_nm) ILIKE #{searchText} ORDER BY t.dcr01_class_tree_cd

SELECT 
  FROM dcr01_class_tree a
 WHERE a.dcr01_company_id = #{companyId}
   AND a.dcr01_class_tree_id IN (
        WITH RECURSIVE ics_tree_down(dcr01_class_tree_id, dcr01_parent_tree_id, dcr01_class_tree_cd, depth, path, cycle) AS (
            SELECT b.dcr01_class_tree_id, b.dcr01_parent_tree_id, b.dcr01_class_tree_cd, 0, ARRAY[b.dcr01_class_tree_cd::text], false
              FROM dcr01_class_tree b
             WHERE b.dcr01_company_id    = #{companyId}
               AND b.dcr01_class_tree_id = #{parentId}
            UNION ALL
            SELECT b.dcr01_class_tree_id, b.dcr01_parent_tree_id, b.dcr01_class_tree_cd, c.depth + 1,
                   array_append(c.path, b.dcr01_class_tree_cd::text), b.dcr01_class_tree_cd = any(c.path)
              FROM dcr01_class_tree b, ics_tree_down c
             WHERE b.dcr01_parent_tree_id = c.dcr01_class_tree_id
               AND b.dcr01_company_id     = #{companyId}
               AND NOT cycle
        )
        SELECT d.dcr01_class_tree_id FROM ics_tree_down d
   )
   AND a.dcr01_type_cd LIKE 'T'
   AND a.dcr01_use_yn = 'true'

   AND CONCAT(a.dcr01_class_tree_cd, a.dcr01_class_tree_nm) LIKE #{searchText}

 ORDER BY a.dcr01_seq

SELECT 
  FROM dcr01_class_tree a
 WHERE a.dcr01_class_tree_id = #{classTreeId}

