UPDATE dcr01_class_tree
   SET dcr01_class_tree_nm  = #{row.classTreeName}
     , dcr01_parent_tree_id = CASE WHEN dcr01_parent_tree_id = 0 THEN 0
                                   ELSE ( SELECT dcr01_class_tree_id
                                            FROM dcr01_class_tree
                                           WHERE dcr01_company_id        = #{companyId}
                                             AND dcr01_insert_bak_dcr_id = #{row.parentTreeId} ) END
     , dcr01_seq            = #{row.seq}
     , dcr01_note           = #{row.note}
     , dcr01_class_tree_cd  = #{row.classTreeCode}
     , dcr01_type_cd        = #{row.typeCode}
 WHERE dcr01_company_id        = #{companyId}
   AND dcr01_insert_bak_dcr_id = #{insertBakDcrId}
   AND COALESCE(dcr01_admin_yn, 'false') = 'true'

